def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 99:
        return 'D'

    my = []
    opp = []
    for a, b in history:
        my.append(a)
        opp.append(b)

    opp_d = 0
    my_d = 0
    for x in opp:
        if x == 'D':
            opp_d += 1
    for x in my:
        if x == 'D':
            my_d += 1

    last_my = my[-1]
    last_opp = opp[-1]

    st_opp = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            st_opp += 1
        else:
            break

    window = n if n < 20 else 20
    recent_opp_c = 0
    for i in range(n - window, n):
        if opp[i] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / window
    overall_rate = (n - opp_d) / n

    forgiven = 0
    punished = 0
    unprovoked = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'C':
                forgiven += 1
            else:
                punished += 1
        elif my[i] == 'C':
            if opp[i + 1] == 'D':
                unprovoked += 1

    recent_my_d = 0
    start = n - 4
    if start < 0:
        start = 0
    for i in range(start, n):
        if my[i] == 'D':
            recent_my_d += 1

    if opp_d == 0:
        if n < 8:
            return 'C'

        if last_opp == 'C':
            if my_d > 0:
                return 'D'

            if n >= 20:
                return 'D'

            if n >= 10 and (n == 10 or rng.random() < 0.3):
                return 'D'

            return 'C'

        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if recent_rate > 0.60:
                return 'C'
            return 'D'

        if recent_my_d > 0 and recent_rate > 0.70 and overall_rate > 0.70:
            if unprovoked <= max(2, n // 20) or punished >= unprovoked:
                return 'C'

            if st_opp <= 3 and forgiven > 0 and punished == 0:
                return 'C'

        if st_opp >= 4 and recent_rate > 0.55 and punished > forgiven:
            return 'C'

        return 'D'

    if punished == 0 and forgiven > 0 and recent_rate > 0.90:
        if last_my == 'D' or rng.random() < 0.25:
            return 'D'

    if n >= 80 and recent_rate > 0.95 and my_d < 10 and rng.random() < 0.08:
        return 'D'

    return 'C'
